{
  "lines": [
    {
      "text": "Von Danzig nach Königsberg und Memel."
    },
    {
      "text": "Den 25ten fuhren wir über die Nehrung nach Elbing, und den 28ten erreichten wir Königsberg"
    },
    {
      "text": "in Preußen. Hier beſuchten wir den Profeſſor Kant, der uns ſehr höflich aufnahm, aber von"
    },
    {
      "text": "ſeiner Philoſophie nicht reden wollte. Die Stadt beſteht eigentlich aus drey Städten, Altſtadt,"
    },
    {
      "text": "Löbenicht und Kneiphof."
    },
    {
      "text": "Den 30ten fuhren wir durch Neuſtadt, ein kleines Städtchen, deſſen Namen man in Deutſchland"
    },
    {
      "text": "wohl hundertmal findet, nach Labiau."
    },
    {
      "text": "Den 2. Auguſt kamen wir nach Memel, der letzten Stadt des Königreichs. Der Hafen war voll"
    },
    {
      "text": "von Schiffen aus Holland und England, welche Holz und Flachs laden."
    },
    {
      "text": "Den 5ten waren wir in Tilſit an der Memel, und kehrten von da über Inſterburg nach"
    },
    {
      "text": "Königsberg zurück."
    },
    {
      "text": "Den 20ten Auguſt erreichten wir auf dem Rückwege Stettin, und den 23ten Colberg, wo dieſes"
    },
    {
      "text": "Tagebuch ſchließt."
    }
  ],
  "script": "fraktur",
  "notes": ""
}

